									"
									@click="pilihAksi(a)"
								>
									<span
										class="text-sm font-semibold"
										:class="
											merah(a.action)
												? 'text-ui-ink-red-600'
												: 'text-ui-ink-gray-800'
										"
										>{{ labelAksi(a.action) }}</span
									>
									<span class="shrink-0 text-xs text-ui-ink-gray-400"
										>→ {{ a.next_state }}</span
									>
								</button>
							</div>

							<p
								v-if="applying"
								class="mt-3 text-center text-xs text-ui-ink-gray-400"
							>
								Menerapkan “{{ labelAksi(applying) }}”…
							</p>
						</div>
					</Transition>
				</div>
			</Transition>
		</Teleport>

		<!-- ===== Sheet: pembagian hari kelebihan (Ketua) ===== -->
		<Teleport to="body">
			<Transition
				enter-active-class="transition-opacity duration-200"
				enter-from-class="opacity-0"
				leave-active-class="transition-opacity duration-150"
				leave-to-class="opacity-0"
			>
				<div
					v-if="bagiOpen"
					class="fixed inset-0 z-[80] flex items-end justify-center bg-black/40"
					@click.self="batalBagi()"
				>
					<Transition
						appear
						enter-active-class="transition-transform duration-200 ease-out"
						enter-from-class="translate-y-full"
						leave-active-class="transition-transform duration-150 ease-in"
						leave-to-class="translate-y-full"
					>
						<div
							v-if="bagiOpen"
							class="w-full max-w-screen-sm rounded-t-3xl bg-ui-surface px-5 pb-[max(1.25rem,env(safe-area-inset-bottom))] pt-3 shadow-2xl"
						>
							<div
								class="mx-auto mb-4 h-1.5 w-10 rounded-full bg-ui-surface-gray-300"
							/>
							<h2
								class="mb-1 text-center text-base font-semibold text-ui-ink-gray-900"
							>
								Bagi {{ angka(d?.hari_kelebihan) }} Hari Kelebihan
							</h2>
							<p class="mb-4 text-center text-xs text-ui-ink-gray-400">
								Pemohon masih harus menyetujui.
							</p>

							<label class="mb-1 block text-xs font-semibold text-ui-ink-gray-500"
								>Hutang cuti (hari)</label
							>
							<input
								v-model.number="bagiHutang"
								type="number"
								min="0"
								step="0.5"
								class="mb-3 w-full rounded-xl border border-ui-line-gray-200 px-3 py-2.5 text-sm text-ui-ink-gray-900 focus:border-primary focus:outline-none"
							/>

							<label class="mb-1 block text-xs font-semibold text-ui-ink-gray-500"
								>Tanpa upah (hari)</label
							>
							<input
								v-model.number="bagiNonPay"
								type="number"
								min="0"
								step="0.5"
								class="mb-3 w-full rounded-xl border border-ui-line-gray-200 px-3 py-2.5 text-sm text-ui-ink-gray-900 focus:border-primary focus:outline-none"
							/>

							<p
								class="mb-3 rounded-xl px-3 py-2 text-xs"
								:class="
									bagiPas
										? 'bg-ui-surface-gray-50 text-ui-ink-gray-500'
										: 'bg-ui-surface-red-50 text-ui-ink-red-600'
								"
							>
								Terbagi {{ angka(bagiTotal) }} dari {{ angka(d?.hari_kelebihan) }}.
								<template v-if="bagiPas && bagiHutang > 12">
									<br />Melebihi jatah setahun, saldo tahun depan minus.
								</template>
							</p>

							<div class="flex gap-2">
								<button
									type="button"
									class="flex-1 rounded-full border border-ui-line-gray-200 py-3 text-sm font-semibold text-ui-ink-gray-600"
									@click="batalBagi()"
								>
									Batal
								</button>
								<button
									type="button"
									:disabled="!bagiPas || !!applying"
									class="flex-1 rounded-full bg-primary py-3 text-sm font-semibold text-ui-onPrimary disabled:opacity-50"
									@click="
										jalankan(aksiBagi, '', {
											hutang: bagiHutang,
											non_pay: bagiNonPay,
										})
									"
								>
									Setujui
								</button>
							</div>
						</div>
					</Transition>
				</div>
			</Transition>
		</Teleport>

		<!-- ===== Sheet: alasan penolakan ===== -->
		<Teleport to="body">
			<Transition
				enter-active-class="transition-opacity duration-200"
				enter-from-class="opacity-0"
				leave-active-class="transition-opacity duration-150"
				leave-to-class="opacity-0"
			>
				<div
					v-if="tolakOpen"
					class="fixed inset-0 z-[80] flex items-end justify-center bg-black/40"
					@click.self="batalTolak()"
				>
					<Transition
						appear
						enter-active-class="transition-transform duration-200 ease-out"
						enter-from-class="translate-y-full"
						leave-active-class="transition-transform duration-150 ease-in"
						leave-to-class="translate-y-full"
					>
						<div
							v-if="tolakOpen"
							class="w-full max-w-screen-sm rounded-t-3xl bg-ui-surface px-5 pb-[max(1.25rem,env(safe-area-inset-bottom))] pt-3 shadow-2xl"
						>
							<div
								class="mx-auto mb-4 h-1.5 w-10 rounded-full bg-ui-surface-gray-300"
							/>
							<h2
								class="mb-1 text-center text-base font-semibold text-ui-ink-gray-900"
							>
								Alasan Penolakan
							</h2>
							<p class="mb-4 text-center text-xs text-ui-ink-gray-400">
								Dibaca pemohon, jadi tuliskan alasan yang jelas.
							</p>

							<textarea
								v-model="alasanTolak"
								rows="4"
								class="w-full resize-none rounded-xl border border-ui-line-gray-200 px-3 py-2.5 text-sm text-ui-ink-gray-900 focus:border-ui-line-gray-200 focus:outline-none focus:ring-0"
							></textarea>

							<div class="mt-4 flex gap-2">
								<button
									type="button"
									class="flex-1 rounded-full border border-ui-line-gray-200 py-3 text-sm font-semibold text-ui-ink-gray-600"
									@click="batalTolak()"
								>
									Batal
								</button>
								<button
									type="button"
									:disabled="!alasanTolak.trim() || !!applying"
									class="flex-1 rounded-full bg-red-600 py-3 text-sm font-semibold text-white disabled:opacity-50"
									@click="jalankan(aksiTolak, alasanTolak.trim())"
								>
									Tolak Pengajuan
								</button>
							</div>
						</div>
					</Transition>
				</div>
			</Transition>
		</Teleport>

		<!-- ============ FORM PENYESUAIAN ============ -->
		<Transition
			enter-active-class="transition-opacity duration-200"
			enter-from-class="opacity-0"
			leave-active-class="transition-opacity duration-150"
			leave-to-class="opacity-0"
		>
			<div
				v-if="penyesuaianOpen"
				class="fixed inset-0 z-50 flex items-end justify-center bg-black/40 sm:items-center"
				@click.self="tutupPenyesuaian"
			>
				<div
					class="max-h-[92vh] w-full max-w-md overflow-y-auto rounded-t-3xl bg-ui-surface p-5 sm:rounded-3xl"
					style="padding-bottom: calc(1.25rem + env(safe-area-inset-bottom))"
				>
					<h2 class="text-lg font-semibold text-ui-ink-gray-900">Ajukan Penyesuaian</h2>
					<p class="mt-1 text-sm text-ui-ink-gray-500">
						Berlaku sekarang: <b>{{ rentang(d.from_date, d.to_date) }}</b>.
					</p>

					<!-- Kalender yang sama dengan form Ajukan Cuti: hari libur ditandai dan
					     jumlah hari kerja rentang baru langsung terlihat. -->
					<CutiDatePicker
						class="mt-3"
						v-model:from="formPenyesuaian.from_date"
						v-model:to="formPenyesuaian.to_date"
						:employee="d.employee"
						judul="Periode Baru"
					/>

					<p
						v-if="pratinjauBatas"
						class="mt-3 rounded-xl border border-ui-line-violet-200 bg-ui-surface-violet-50 px-3 py-2.5 text-sm text-ui-ink-violet-800"
					>
						Kelebihan <b>{{ angka(pratinjauBatas) }} hari kerja</b> dari batas
						{{ d.batas_hari_sakit }} hari kerja.
					</p>

					<label class="mt-3 block text-sm font-medium text-ui-ink-gray-700"
						>Alasan <span class="text-ui-ink-red-500">*</span></label
					>
					<textarea
						v-model="formPenyesuaian.reason"
						rows="3"
						maxlength="1000"
						placeholder="Mis. sakit berlanjut, ada surat dokter baru"
						class="mt-1.5 w-full resize-none rounded-xl border border-ui-line-gray-200 bg-ui-surface-gray-50 p-3 text-base text-ui-ink-gray-900 placeholder:text-ui-ink-gray-400 focus:border-primary focus:bg-ui-surface focus:outline-none"
					></textarea>

					<p v-if="galatPenyesuaian" class="mt-2 text-sm text-ui-ink-red-600">
						{{ galatPenyesuaian }}
					</p>

					<div class="mt-5 flex gap-2">
						<button
							type="button"
							class="flex-1 rounded-xl border border-ui-line-gray-200 py-3 text-base font-medium text-ui-ink-gray-700 active:bg-ui-surface-gray-100"
							:disabled="mengajukan"
							@click="tutupPenyesuaian"
						>
							Batal
						</button>
						<button
							type="button"
							class="flex-1 rounded-xl bg-primary py-3 text-base font-semibold text-ui-onPrimary active:opacity-90 disabled:opacity-60"
							:disabled="!bisaAjukanPenyesuaian || mengajukan"
							@click="kirimPenyesuaian"
						>
							{{ mengajukan ? 'Mengirim…' : 'Ajukan' }}
						</button>
					</div>
				</div>
			</div>
		</Transition>
	</div>
</template>

<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { createResource, toast } from 'frappe-ui'
import { refreshCsrfToken } from '../data/session'
import { statusBadge, rentang, angka, tanggal } from '../data/cutiStatus'
import { openAttachment } from '../composables/pdfViewer'
import CutiDatePicker from '../components/CutiDatePicker.vue'
import { useBackNavigation } from '../composables/useBackNavigation'
import { konfirmasi } from '../composables/konfirmasi'

const props = defineProps({ name: { type: String, required: true } })

// Dibuka dari menu Pengajuan Cuti Karyawan (?origin=) -> kembali ke sana.
const { backTarget } = useBackNavigation({ name: 'Cuti' }, 'Cuti')

const d = ref(null)
const loading = ref(true)
const applying = ref('')
const actionsOpen = ref(false)
const tolakOpen = ref(false)
const aksiTolak = ref('')
const alasanTolak = ref('')
const bagiOpen = ref(false)
const aksiBagi = ref('')
const bagiHutang = ref(0)
const bagiNonPay = ref(0)
const inputFile = ref(null)
const unggah = ref(false)

const detailRes = createResource({
	url: 'juragan.api.portal.cuti.get_detail',
	method: 'GET',
	auto: false,
	makeParams: () => ({ name: props.name }),
	onSuccess: (data) => {
		d.value = data
	},
})

const errorMessage = computed(() => {
	if (!detailRes.error) return ''
	const e = detailRes.error
	return e?.messages?.[0] || e?.message || 'Gagal memuat pengajuan.'
})

// Penyesuaian yang menunggu jawaban pemilik cuti ini (lihat kotak di atas).
const pm = computed(() => d.value?.penyesuaian_menunggu || null)
const rincianPm = computed(() =>
	[
		{ hari: Number(pm.value?.sakit_potong_tahunan || 0), label: 'potong cuti tahunan' },
		{ hari: Number(pm.value?.sakit_non_pay || 0), label: 'tanpa upah' },
	].filter((b) => b.hari)
)
// Aksi cuti + aksi jawaban penyesuaian (ditandai `penyesuaian`) di satu daftar
// Action, sama dengan tombol Action di Detail Penyesuaian.
const daftarAksi = computed(() => [
	...(d.value?.actions || []),
	...(pm.value?.actions || []).map((a) => ({ ...a, penyesuaian: pm.value.name })),
])
const adaAksi = computed(() => daftarAksi.value.length > 0)

// ===== Penyesuaian periode (diajukan pemilik cuti) =====
const router = useRouter()
const penyesuaianOpen = ref(false)
const mengajukan = ref(false)
const galatPenyesuaian = ref('')
const formPenyesuaian = reactive({
	from_date: '',
	to_date: '',
	reason: '',
})

const bisaAjukanPenyesuaian = computed(
	() =>
		!!formPenyesuaian.from_date &&
		!!formPenyesuaian.to_date &&
		!!formPenyesuaian.reason.trim()
)

function bukaPenyesuaian() {
	// Titik berangkat = periode yang berlaku sekarang; tinggal menggeser ujungnya.
	formPenyesuaian.from_date = d.value.from_date
	formPenyesuaian.to_date = d.value.to_date || ''
	formPenyesuaian.reason = ''
	galatPenyesuaian.value = ''
	penyesuaianOpen.value = true
}

function tutupPenyesuaian() {
	if (mengajukan.value) return
	penyesuaianOpen.value = false
}

const rincianSakit = computed(() =>
	[
		{ hari: Number(d.value?.sakit_potong_tahunan || 0), label: 'potong cuti tahunan' },
		{ hari: Number(d.value?.sakit_non_pay || 0), label: 'tanpa upah' },
	].filter((b) => b.hari)
)

// Pratinjau berapa hari kerja rentang baru melewati batas sakit — hanya
// informasi; angka pastinya dihitung ulang server saat Ketua memutuskan.
const pratinjauBatas = ref(0)
let pratinjauTimer = null
watch(
	() => [penyesuaianOpen.value, formPenyesuaian.from_date, formPenyesuaian.to_date],
	() => {
		clearTimeout(pratinjauTimer)
		if (!penyesuaianOpen.value || !d.value?.sakit || !formPenyesuaian.from_date) {
			pratinjauBatas.value = 0
			return
		}
		if (!formPenyesuaian.to_date) return
		pratinjauTimer = setTimeout(async () => {
			try {
				const r = await createResource({
					url: 'juragan.api.portal.penyesuaian_cuti.pratinjau_batas',
					method: 'GET',
				}).fetch({
					leaves_to_adjust: props.name,
					from_date: formPenyesuaian.from_date,
					to_date: formPenyesuaian.to_date,
				})
				pratinjauBatas.value = Number(r?.hari || 0)
			} catch {
				pratinjauBatas.value = 0
			}
		}, 300)
	}
)

const ajukanPenyesuaianRes = createResource({
	url: 'juragan.api.portal.penyesuaian_cuti.ajukan',
	method: 'POST',
	auto: false,
})

async function kirimPenyesuaian() {
	if (!bisaAjukanPenyesuaian.value || mengajukan.value) return
	mengajukan.value = true
	galatPenyesuaian.value = ''
	try {
		await refreshCsrfToken()
		const hasil = await ajukanPenyesuaianRes.submit({
			leaves_to_adjust: props.name,
			from_date: formPenyesuaian.from_date,
			to_date: formPenyesuaian.to_date,
			reason: formPenyesuaian.reason.trim(),
		})
		penyesuaianOpen.value = false
		toast.success('Penyesuaian diajukan, menunggu persetujuan.')
		router.push({ name: 'PenyesuaianCutiDetail', params: { name: hasil.name } })
	} catch (e) {
		galatPenyesuaian.value = e?.messages?.[0] || e?.message || String(e)
	} finally {
		mengajukan.value = false
	}
}

// Kelebihan dianggap sudah diputuskan bila pembagiannya menutup seluruhnya.
const sudahDibagi = computed(() => {
	const x = d.value
	if (!x?.hari_kelebihan) return false
	return Math.abs(x.hari_hutang_cuti + x.hari_non_pay - x.hari_kelebihan) < 0.001
})

const bagiTotal = computed(() => Number(bagiHutang.value || 0) + Number(bagiNonPay.value || 0))
const bagiPas = computed(
	() =>
		Number(bagiHutang.value || 0) >= 0 &&
		Number(bagiNonPay.value || 0) >= 0 &&
		Math.abs(bagiTotal.value - Number(d.value?.hari_kelebihan || 0)) < 0.001
)

/**
 * Tiga tahap tetap: diajukan karyawan → diperiksa atasan → diputuskan HR.
 * Tahap atasan disembunyikan bila karyawannya memang tidak punya atasan,
 * supaya garis waktunya tidak memperlihatkan langkah yang tidak akan terjadi.
 */
const tahapan = computed(() => {
	const x = d.value
	if (!x) return []
	const s = x.status
	const out = []
	// Pemohon orang HR, atau HR mengajukan untuk karyawan lain: langsung ke
	// Ketua, tahap Atasan & HR tidak pernah terjadi.
	const langsungKetua = x.pemohon_hr || x.diajukan_hr

	out.push({
		label: x.diajukan_hr ? 'Diajukan HR' : 'Diajukan karyawan',
		detail:
			s === 'Draft' ? 'Draft, belum dikirim' : `Dibuat ${tanggal(x.posting_date)}`,
		state: s === 'Draft' ? 'active' : 'done',
	})

	if (x.atasan && !langsungKetua) {
		let state = 'todo'
		let detail = `Menunggu ${x.atasan}`
		if (x.disetujui_atasan) {
			const ditolak = s === 'Rejected' && !x.leave_approver
			state = ditolak ? 'reject' : 'done'
			detail = `${ditolak ? 'Ditolak' : 'Disetujui'} ${x.disetujui_atasan}`
		} else if (s === 'Menunggu Approval Atasan') {
			state = 'active'
		}
		out.push({ label: 'Persetujuan atasan', detail, state })
	}

	// Tahap HR. Dilewati bila langsung ke Ketua: menampilkan langkah yang tidak
	// akan terjadi hanya menyesatkan.
	if (!langsungKetua) {
		let st = 'todo'
		let detail = 'Menunggu HR'
		if (x.leave_approver) {
			const ditolak = s === 'Rejected' && !x.disetujui_direktur
			st = ditolak ? 'reject' : 'done'
			detail = `${ditolak ? 'Ditolak' : 'Disetujui'} ${x.leave_approver}`
		} else if (s === 'Menunggu Approval HR') {
			st = 'active'
		} else if (s === 'Rejected') {
			detail = 'Tidak sampai ke HR'
		}
		out.push({ label: 'Persetujuan HR', detail, state: st })
	}

	// Tahap akhir: Ketua memutuskan seluruh pengajuan.
	let dirState = 'todo'
	let dirDetail = 'Menunggu Ketua'
	if (x.disetujui_direktur) {
		dirState = s === 'Rejected' ? 'reject' : 'done'
		dirDetail = `${s === 'Rejected' ? 'Ditolak' : 'Disetujui'} ${x.disetujui_direktur}`
	} else if (s === 'Menunggu Approval Ketua') {
		dirState = 'active'
	} else if (s === 'Rejected') {
		dirDetail = 'Tidak sampai ke Ketua'
	}
	out.push({ label: 'Keputusan Ketua', detail: dirDetail, state: dirState })

	// Tahap tambahan yang hanya ada bila cutinya melebihi saldo: pemohon
	// menanggung konsekuensinya, jadi ia yang mengucapkan kata terakhir.
	if (x.hari_kelebihan) {
		let st = 'todo'
		let detail = 'Menunggu jawaban pemohon'
		if (x.keputusan_karyawan === 'Setuju') {
			st = 'done'
			detail = 'Diterima pemohon'
		} else if (x.keputusan_karyawan === 'Tidak Setuju') {
			st = 'reject'
			detail = 'Ditolak pemohon'
		} else if (s === 'Menunggu Persetujuan Karyawan') {
			st = 'active'
		} else if (s === 'Rejected') {
			detail = 'Tidak sampai ke pemohon'
		}
		out.push({ label: 'Persetujuan pemohon', detail, state: st })
	}

	if (s === 'Cancelled') {
		out.push({ label: 'Dibatalkan', detail: 'Pengajuan dibatalkan', state: 'reject' })
	}
	return out
})

function namaFile(url) {
	if (!url) return ''
	const bersih = String(url).split('?')[0]
	return decodeURIComponent(bersih.substring(bersih.lastIndexOf('/') + 1)) || bersih
}

function pilihFile() {
	if (!inputFile.value) return
	inputFile.value.value = ''
	inputFile.value.click()
}

const mcRes = createResource({
	url: 'juragan.api.portal.cuti.lampirkan_mc',
	method: 'POST',
})

// Berkasnya diunggah dulu, baru ditunjuk dokumennya — server yang menautkan
// keduanya supaya approver ikut bisa membukanya.
async function simpanMc(fileUrl) {
	await mcRes.submit({ name: props.name, file_url: fileUrl })
	await detailRes.fetch()
}

async function unggahMc(e) {
	const file = e.target.files?.[0]
	if (!file) return
	const MAKS_MB = 3
	if (file.size > MAKS_MB * 1024 * 1024) {
		toast.error(`Ukuran file maksimal ${MAKS_MB} MB.`)
		return
	}
	unggah.value = true
	try {
		const fd = new FormData()
		fd.append('file', file, file.name)
		fd.append('upload_doctype', 'Pengajuan Cuti')
		fd.append('is_private', '1')
		const res = await fetch('/api/method/upload_file', {
			method: 'POST',
			credentials: 'include',
			headers: {
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: fd,
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(json?.exception || json?.message || `HTTP ${res.status}`)
		await simpanMc(json.message?.file_url || '')
		toast.success('Surat dokter terlampir')
	} catch (err) {
		toast.error(err?.messages?.[0] || err.message || 'Gagal mengunggah lampiran.')
	} finally {
		unggah.value = false
	}
}

async function hapusMc() {
	if (unggah.value) return
	if (!(await konfirmasi({ judul: 'Hapus lampiran surat dokter?', label: 'Hapus', bahaya: true })))
		return
	unggah.value = true
	try {
		await simpanMc('')
		toast.success('Lampiran dihapus')
	} catch (err) {
		toast.error(err?.messages?.[0] || err.message || 'Gagal menghapus lampiran.')
	} finally {
		unggah.value = false
	}
}

function merah(a) {
	return /reject|tolak|cancel|batal|tidak setuju/i.test(a || '')
}
function labelAksi(a) {
	return (
		{
			Approve: 'Setujui',
			Reject: 'Tolak',
			Cancel: 'Batalkan',
			'Ajukan Cuti': 'Ajukan Cuti',
			Setuju: 'Terima Keputusan',
			'Tidak Setuju': 'Tolak Keputusan',
		}[a] || a
	)
}

// Cancel perlu konfirmasi: dari status Approved ia memulihkan saldo dan
// membatalkan Kehadiran — bukan sekadar mengubah label.
function butuhKonfirmasi(a) {
	return a === 'Cancel' || a === 'Tidak Setuju'
}

// Penolakan tidak boleh langsung jalan: alasannya diminta dulu, karena yang
// ditolak berhak tahu kenapa. Yang menentukan tujuan transisinya, bukan nama
// aksinya — nama bisa diubah di Workflow, statusnya tidak.
function pilihAksi(a) {
	if (a.penyesuaian) {
		jawabPenyesuaian(a.penyesuaian, a.action)
		return
	}
	if (a.next_state === 'Rejected') {
		aksiTolak.value = a.action
		alasanTolak.value = ''
		tolakOpen.value = true
		return
	}
	// Menuju tahap pemohon berarti Ketua harus menentukan dulu perlakuan
	// hari yang melebihi saldo — persetujuannya tidak berarti apa-apa tanpa itu.
	if (a.next_state === 'Menunggu Persetujuan Karyawan') {
		aksiBagi.value = a.action
		bagiHutang.value = Number(d.value?.hari_kelebihan || 0)
		bagiNonPay.value = 0
		bagiOpen.value = true
		return
	}
	jalankan(a.action)
}

function batalBagi() {
	if (applying.value) return
	bagiOpen.value = false
	aksiBagi.value = ''
}

function batalTolak() {
	if (applying.value) return
	tolakOpen.value = false
	aksiTolak.value = ''
	alasanTolak.value = ''
}

// Jawaban atas pembagian Ketua di penyesuaian; sama dengan Detail Penyesuaian.
async function jawabPenyesuaian(nama, action) {
	if (applying.value) return
	actionsOpen.value = false
	if (action === 'Tidak Setuju') {
		const setuju = await konfirmasi({
			judul: 'Tolak keputusan Ketua?',
			pesan: `Penyesuaian akan batal dan hari setelah hari kerja ke-${pm.value?.batas_hari_sakit || 14} dihitung Absen jika tidak masuk kerja.`,
			label: 'Tolak',
			bahaya: true,
		})
		if (!setuju) return
	}
	applying.value = action
	try {
		await refreshCsrfToken()
		await createResource({
			url: 'juragan.api.portal.penyesuaian_cuti.putuskan',
			method: 'POST',
		}).submit({ name: nama, action })
		await detailRes.fetch()
		toast.success(
			action === 'Setuju' ? 'Diterima. Penyesuaian berlaku.' : 'Ditolak. Penyesuaian batal.'
		)
	} catch (e) {
		toast.error(e?.messages?.[0] || e?.message || 'Gagal menyimpan jawaban.')
	} finally {
		applying.value = ''
	}
}

async function jalankan(action, alasan = '', pembagian = null) {
	if (applying.value) return
	if (
		butuhKonfirmasi(action) &&
		!(await konfirmasi(
			action === 'Tidak Setuju'
				? { judul: 'Tolak dan batalkan pengajuan ini?', label: 'Tolak', bahaya: true }
				: { judul: 'Batalkan pengajuan cuti ini?', label: 'Batalkan', bahaya: true }
		))
	)
		return
	applying.value = action
	try {
		await createResource({
			url: 'juragan.api.portal.cuti.apply_transition',
			method: 'POST',
		}).submit({
			name: props.name,
			action,
			...(alasan ? { alasan } : {}),
			...(pembagian || {}),
		})
		await detailRes.fetch()
		toast.success(
			{
				Reject: 'Pengajuan ditolak',
				Cancel: 'Pengajuan dibatalkan',
				Setuju: 'Cuti disetujui dan berlaku',
				'Tidak Setuju': 'Pengajuan dibatalkan',
			}[action] || 'Pengajuan disetujui'
		)
	} catch (e) {
		toast.error(e?.messages?.[0] || e?.message || 'Gagal memproses aksi.')
	} finally {
		applying.value = ''
		actionsOpen.value = false
		tolakOpen.value = false
		bagiOpen.value = false
	}
}

onMounted(async () => {
	try {
		await detailRes.fetch()
	} finally {
		loading.value = false
	}
})
</script>
